//! Gold: `corpus` is 1:1 with the live `harness/electronics/corpus.py`.
//!
//! `tests/fixtures/gold/corpus_v1.json` was generated by
//! `scripts/gold_corpus.py` — `build` cases materialise a fixture tree and run
//! the reference's `build_corpus_registry` end to end, kernel cases call the
//! pure readers, and every expected outcome (including error messages) is
//! captured from the reference. Absolute paths are volatile, so both sides
//! normalise the tree root to `$ROOT` and re-derive `evidence_sha256` over the
//! normalised core — which makes each digest a live differential check of
//! `canonical_json` + SHA-256 against Python's `hashlib`.
//!
//! The cases pin the traps the registry exists for: duplicate PDF bytes stay
//! ONE document carrying both paths, `document_sha256` joins are `direct`,
//! vendor+part joins are `unambiguous_part`, ambiguous and unresolved rows
//! count apart, orphan ground truth carries its reason, the source audit's
//! multi-row-per-PDF lists join and its stale hashes are an error,
//! `_`-prefixed validated subdirectories are skipped, `records` lists and
//! whole-object JSON assets both feed rows, and `write_new_registry` is
//! exclusive and read-only.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::cast_precision_loss,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::{Map, Value};

use dw_recon::corpus::{
    build_corpus_registry, canonical_json_sha256, canonical_vendor, document_digest, part_key,
    record_ids, record_summary, verify_corpus_registry, write_new_registry, AssetSource,
    CorpusInputs,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/corpus_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// A scratch tree root that resolves like the generator's.
fn temp_root(name: &str) -> PathBuf {
    let root = std::env::temp_dir().join(format!(
        "corpus_gold_{}_{}",
        std::process::id(),
        name.replace(['/', ' '], "_")
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).unwrap();
    fs::canonicalize(&root).unwrap_or(root)
}

/// `str.replace(root, "$ROOT")` over every string in the tree.
fn normalise(value: &mut Value, root: &str) {
    match value {
        Value::String(s) => *s = s.replace(root, "$ROOT"),
        Value::Array(list) => {
            for item in list {
                normalise(item, root);
            }
        }
        Value::Object(map) => {
            for (_, item) in map.iter_mut() {
                normalise(item, root);
            }
        }
        _ => {}
    }
}

/// Strip `created_at`, then re-derive `evidence_sha256` over what is left —
/// exactly what the generator does after `$ROOT` normalisation.
fn reissue_digest(registry: &mut Value) {
    if let Some(map) = registry.as_object_mut() {
        map.remove("created_at");
    }
    let core = {
        let mut map = Map::new();
        for (key, item) in registry.as_object().into_iter().flatten() {
            if key != "evidence_sha256" {
                map.insert(key.clone(), item.clone());
            }
        }
        Value::Object(map)
    };
    if let Some(map) = registry.as_object_mut() {
        map.insert(
            "evidence_sha256".into(),
            Value::String(canonical_json_sha256(&core)),
        );
    }
}

fn write_tree(root: &Path, tree: &Value) {
    for entry in tree.as_array().into_iter().flatten() {
        let rel = entry["path"].as_str().unwrap();
        let target = root.join(rel);
        fs::create_dir_all(target.parent().unwrap()).unwrap();
        let bytes: Vec<u8> = entry["bytes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_u64().unwrap() as u8)
            .collect();
        fs::write(&target, bytes).unwrap();
    }
}

fn corpus_inputs(
    root: &Path,
    config: &Value,
) -> Result<CorpusInputs, dw_recon::corpus::CorpusError> {
    // The generator always materialises the three roots.
    for key in ["pdfs", "gt", "validated"] {
        fs::create_dir_all(root.join(key)).unwrap();
    }
    let rel = |key: &str, default: &str| -> PathBuf {
        root.join(config[key].as_str().unwrap_or(default))
    };
    Ok(CorpusInputs {
        pdf_root: rel("pdf_root", "pdfs"),
        ground_truth_root: rel("ground_truth_root", "gt"),
        validated_root: rel("validated_root", "validated"),
        source_audit: config
            .get("source_audit")
            .and_then(Value::as_str)
            .map(|p| root.join(p)),
        row_dataset_manifest: config
            .get("row_dataset_manifest")
            .and_then(Value::as_str)
            .map(|p| root.join(p)),
        assets: config
            .get("assets")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .map(|a| {
                AssetSource::new(
                    a["name"].as_str().unwrap(),
                    root.join(a["path"].as_str().unwrap()),
                    a.get("kind").and_then(Value::as_str).unwrap_or("auto"),
                )
            })
            .collect::<Result<Vec<_>, _>>()?,
        expected_pdf_files: config
            .get("expected_pdf_files")
            .and_then(Value::as_u64)
            .map(|n| n as usize),
    })
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "build" => {
                let root = temp_root(name);
                write_tree(&root, &case["input"]["tree"]);
                let root_str = root.display().to_string();
                let outcome = corpus_inputs(&root, &case["input"]["config"])
                    .and_then(|inputs| build_corpus_registry(&inputs, 2));
                match outcome {
                    Ok(registry) => {
                        let failure = case.get("error").and_then(Value::as_object);
                        assert!(
                            failure.is_none(),
                            "case {name}: expected error {:?}",
                            case["error"]
                        );
                        let mut got = registry;
                        normalise(&mut got, &root_str);
                        reissue_digest(&mut got);
                        assert_eq!(got, case["expected"], "case {name}");
                    }
                    Err(error) => {
                        let mut message = error.to_string();
                        message = message.replace(&root_str, "$ROOT");
                        let expect = case["error"].as_object().unwrap();
                        let want = expect["message"].as_str().unwrap();
                        match expect["match"].as_str().unwrap() {
                            "exact" => {
                                assert_eq!(message, want, "case {name}");
                            }
                            "contains" => {
                                assert!(
                                    message.contains(want),
                                    "case {name}: {message} does not contain {want}"
                                );
                            }
                            other => panic!("unknown error match {other}"),
                        }
                    }
                }
                let _ = fs::remove_dir_all(&root);
            }
            "canonical_vendor" => {
                let got = canonical_vendor(&case["input"]["value"]);
                let expected: Option<String> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "part_key" => {
                let got = part_key(&case["input"]["value"]);
                let expected: Option<String> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "record_ids" => {
                let got = record_ids(
                    &case["input"]["row"],
                    case["input"]["fallback"].as_str().unwrap(),
                );
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "document_digest" => {
                let got = document_digest(&case["input"]["row"]);
                let expected: Option<String> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "record_summary" => {
                let got = record_summary(
                    case["input"]["rel_path"].as_str().unwrap(),
                    case["input"]["digest"].as_str().unwrap(),
                    &case["input"]["value"],
                );
                assert_eq!(got, case["expected"], "case {name}");
            }
            "canonical_json_sha256" => {
                let got = canonical_json_sha256(&case["input"]["value"]);
                assert_eq!(got, case["expected"].as_str().unwrap(), "case {name}");
            }
            "verify" => {
                let got = verify_corpus_registry(&case["input"]["value"]);
                let expect = case["expected"].as_object().unwrap();
                match (expect["ok"].as_bool().unwrap(), got) {
                    (true, Ok(())) => {}
                    (false, Err(error)) => {
                        assert_eq!(
                            error.to_string(),
                            expect["message"].as_str().unwrap(),
                            "case {name}"
                        );
                    }
                    (ok, result) => panic!(
                        "case {name}: expected ok={ok}, got {}",
                        result.map_or_else(|e| e.to_string(), |()| "ok".to_string())
                    ),
                }
            }
            "write" => {
                let root = temp_root(name);
                let value = case["input"]["value"].clone();
                let destination = root.join("registry.json");
                write_new_registry(&destination, &value).unwrap();
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    let mode = fs::metadata(&destination).unwrap().permissions().mode();
                    assert_eq!(
                        format!("{:04o}", mode & 0o777),
                        case["expected"]["mode"].as_str().unwrap(),
                        "case {name}"
                    );
                }
                let error = write_new_registry(&destination, &value).unwrap_err();
                let mut message = error.to_string();
                message = message.replace(&root.display().to_string(), "$ROOT");
                assert_eq!(
                    message,
                    case["expected"]["error"].as_str().unwrap(),
                    "case {name}"
                );
                let _ = fs::remove_dir_all(&root);
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
